(function () {
  "use strict";
  // Layer JS loads on every page: it does nothing without a workbench.
  var workbench = document.querySelector("[data-studio-workbench]");
  if (!workbench) {
    return;
  }
  // studio.js (studio:studio, order 0) runs first and gives the API.
  var S = window.ScrudStudio;
  if (!S) return;

  // The rule editor: a stylesheet in the Editor pane. Focus on a rule's row
  // marks the rule's matches in the live preview (`mark`), with the
  // stylesheet as the form shows it as a draft; the preview's bridge
  // answers with the counts, shown under the rows.
  var SHEET = '[data-studio-editor-item][data-studio-kind="stylesheet"]';
  var DRAFT_DELAY = 300;
  var editorBody = workbench.querySelector("[data-studio-editor]");
  // The marked row: {editor, index}, or null.
  var marked = null;
  var blurTimer = null;
  var typeTimer = null;
  // The request rules.js last sent (JSON), so typing that changes nothing
  // sends nothing.
  var lastSent = null;

  function isIndex(text) {
    return /^(0|[1-9][0-9]*)$/.test(String(text));
  }

  // The stylesheet editor `target` is in, inside the Editor pane, or null.
  function sheetOf(target) {
    if (!editorBody || !target || typeof target.closest !== "function") return null;
    if (!editorBody.contains(target)) return null;
    return target.closest(SHEET);
  }

  // The rule index of the row `target` is in, or null.
  function rowIndex(target, editor) {
    var row = target.closest("[data-studio-rule-index]");
    if (!row || !editor.contains(row)) return null;
    var index = row.getAttribute("data-studio-rule-index");
    return isIndex(index) ? Number(index) : null;
  }

  // The stylesheet as the form shows it: the frame's content with its
  // inputs applied, as its save would build it (ScrudUI.buildBody). None
  // on a published T or in view mode: the preview then marks the stored
  // stylesheet.
  function formOf(editor) {
    if (S.published || editor.getAttribute("data-studio-mode") !== "edit") return null;
    var UI = window.ScrudUI;
    var frame = editor.closest(".scrud-resource");
    if (!UI || !frame || !frame.hasAttribute("hx-put")) return null;
    var stored = S.contentOf(frame);
    if (!stored || typeof stored !== "object" || Array.isArray(stored)) return null;
    var content = UI.buildBody(stored, UI.fieldsOf(frame), []);
    return { stored: stored, content: content };
  }

  // The preview's extras for `editor`: the mark of rule `index` (null: no
  // mark), and the form as a draft when marking, or when it differs from
  // the stored stylesheet.
  function extraFor(editor, index) {
    var form = formOf(editor);
    var extra = {};
    var changed = form && JSON.stringify(form.content) !== JSON.stringify(form.stored);
    if (form && (index !== null || changed)) {
      extra.drafts = [{ kind: "stylesheet", content: form.content }];
    }
    if (index !== null) {
      var name = form ? form.content.name : editor.getAttribute("data-studio-stylesheet");
      var appliesTo = form
        ? form.content.applies_to
        : editor.getAttribute("data-studio-applies-to");
      extra.mark = {
        stylesheet: String(name || ""),
        applies_to: typeof appliesTo === "string" ? appliesTo : "",
        index: index
      };
    }
    return extra;
  }

  function send(editor, index) {
    var extra = extraFor(editor, index);
    lastSent = JSON.stringify(extra);
    S.submitPreview(extra);
  }

  function countsOf(editor) {
    return editor ? editor.querySelector("[data-studio-rule-counts]") : null;
  }

  function showCounts(editor, text) {
    var counts = countsOf(editor);
    if (!counts) return;
    counts.textContent = text;
    if (text) counts.removeAttribute("hidden");
    else counts.setAttribute("hidden", "");
  }

  function cancel(timer) {
    if (timer !== null) window.clearTimeout(timer);
    return null;
  }

  // Focus on a row (its inputs, its buttons, a view row): mark its rule.
  // Moving within the row keeps the mark as it is.
  workbench.addEventListener("focusin", function (evt) {
    var editor = sheetOf(evt.target);
    if (!editor) return;
    var index = rowIndex(evt.target, editor);
    if (index === null) return;
    var same = marked && marked.editor === editor && marked.index === index;
    blurTimer = cancel(blurTimer);
    if (same) return;
    marked = { editor: editor, index: index };
    showCounts(editor, "");
    send(editor, index);
  });

  // Leaving the rows clears the mark (once focus has settled: from one row
  // to another is a new mark, not a clear).
  workbench.addEventListener("focusout", function (evt) {
    if (!marked || !sheetOf(evt.target)) return;
    blurTimer = cancel(blurTimer);
    blurTimer = window.setTimeout(function () {
      blurTimer = null;
      var editor = marked ? marked.editor : null;
      marked = null;
      if (!editor || !editorBody.contains(editor)) return;
      showCounts(editor, "");
      send(editor, null);
    }, 0);
  });

  // Typing in a field: the form again, once the typing pauses, with the
  // mark if a row has it. Nothing on a published T or in view mode.
  workbench.addEventListener("keyup", function (evt) {
    var target = evt.target;
    var editor = sheetOf(target);
    if (!editor || !target.closest("[data-studio-field]")) return;
    if (!formOf(editor)) return;
    typeTimer = cancel(typeTimer);
    typeTimer = window.setTimeout(function () {
      typeTimer = null;
      if (!editorBody.contains(editor)) return;
      var index = marked && marked.editor === editor ? marked.index : null;
      var extra = extraFor(editor, index);
      if (JSON.stringify(extra) === lastSent) return;
      send(editor, index);
    }, DRAFT_DELAY);
  });

  // A new prefix: its IRI input is named by the key the author types
  // (/prefixes/<key>, escaped as a JSON Pointer), so the frame's save
  // applies it; no key, no name.
  workbench.addEventListener("input", function (evt) {
    var target = evt.target;
    if (!sheetOf(target) || !target.hasAttribute("data-studio-prefix-key")) return;
    var row = target.closest("[data-studio-prefix-new]");
    var iri = row ? row.querySelector("[data-studio-prefix-iri]") : null;
    if (!iri) return;
    var key = String(target.value || "");
    if (key) {
      iri.setAttribute("name", "/prefixes/" + key.replace(/~/g, "~0").replace(/\//g, "~1"));
    } else {
      iri.removeAttribute("name");
    }
  });

  // A new editor (another item, a save's response): no row is marked.
  document.addEventListener("htmx:afterSwap", function (evt) {
    var target = evt.target;
    if (!target || !editorBody) return;
    if (target !== editorBody && !editorBody.contains(target)) return;
    if (marked && !editorBody.contains(marked.editor)) marked = null;
    blurTimer = cancel(blurTimer);
    typeTimer = cancel(typeTimer);
    lastSent = null;
  });

  // The bridge's counts of the marked nodes: only from the preview's own
  // window, only this shape (the branch's scripts can post too), and only
  // while a row is marked.
  window.addEventListener("message", function (evt) {
    var frame = workbench.querySelector("iframe.studio-preview");
    if (!frame || !frame.contentWindow || evt.source !== frame.contentWindow) return;
    var data = evt.data;
    if (!data || typeof data !== "object" || data.type !== "scrud-preview:marks") return;
    var wins = data.wins;
    var loses = data.loses;
    if (!isCount(wins) || !isCount(loses)) return;
    if (!marked || !editorBody.contains(marked.editor)) return;
    showCounts(marked.editor, "matches " + (wins + loses) + " nodes, wins on " + wins);
  });

  function isCount(value) {
    return (
      typeof value === "number" && isFinite(value) && value >= 0 && Math.floor(value) === value
    );
  }
})();
